      romeinen: [
        ['Welche Stadt war die Hauptstadt des Römischen Reiches?','Rom',['Athen','Paris','Kairo'],'Alle Wege führten dorthin.','Rom war der Mittelpunkt des Reiches, mit dem Kaiser und dem Senat.','Jeder Meilenstein an den Straßen zählte die Entfernung nach Rom.',1],
        ['Welches Tier säugte der Sage nach Romulus und Remus?','Eine Wölfin',['Ein Bär','Ein Adler','Eine Ziege'],'Sie fand die Babys am Fluss.','Die Sage erzählt, eine Wölfin säugte die Zwillinge, die Rom gründeten.','Die Statue der Wölfin ist bis heute das Zeichen Roms.',1],
        ['Was ist eine Toga?','Ein langes Gewand',['Ein Helm','Ein Schwert','Ein Schiff'],'Man legt sie über die Schulter.','Die Toga war eine Bahn Wolle, die um den Körper gelegt wurde.','Nur römische Bürger durften eine Toga tragen.',1],
        ['Was zogen die Pferde in der römischen Arena?','Einen Streitwagen',['Ein Auto','Einen Zug','Ein Fahrrad'],'Zwei Räder und viel Staub.','Wagenrennen war der beliebteste Sport, mit vier Mannschaften in Farben.','In den Circus Maximus passten über hunderttausend Zuschauer.',1],
        ['In welchem Land liegt Rom?','In Italien',['In Spanien','In Ägypten','In Griechenland'],'Das Land hat die Form eines Stiefels.','Rom liegt am Fluss Tiber, mitten in Italien.','Mitten in Rom liegt ein winziges eigenes Land: die Vatikanstadt.',1],
        ['Wer waren die Gladiatoren?','Kämpfer in der Arena',['Bäcker','Bauern','Priester'],'Das Publikum jubelte ihnen zu.','Gladiatoren kämpften vor Publikum, oft mit Schild, Helm und Schwert.','Die berühmtesten waren bekannt wie heute Stars.',2],
        ['Was war eine römische Villa?','Ein großes Landhaus',['Ein kleines Boot','Eine Brotsorte','Eine Waffe'],'Draußen vor der Stadt, mit Garten.','Reiche Römer hatten eine Villa auf dem Land, mit Innenhof und Brunnen.','Unter vielen Villen lagen Keller voller Wein und Olivenöl.',2],
        ['Was trugen Römer an den Füßen?','Ledersandalen',['Holzschuhe','Gummistiefel','Wollpantoffeln'],'Riemen und Nägel.','Soldaten trugen Sandalen mit Nägeln in der Sohle, für besseren Halt.','So eine Sohle war nach rund fünfhundert Kilometern durch.',2],
        ['Wer machte die schwerste Arbeit in einem römischen Haus?','Die Sklaven',['Die Kaiser','Die Senatoren','Die Soldaten'],'Sie hatten keine Wahl.','Sklaven erledigten Haus, Felder und Bergwerke, ohne Lohn und Freiheit.','Manche wurden frei und führten später einen eigenen Laden.',2],
        ['Was war eine Amphore?','Ein großer Tonkrug',['Eine Schiffsart','Ein Helm','Eine Münze'],'Unten lief sie spitz zu.','In Amphoren brachten Römer Wein, Öl und Fischsoße übers Meer.','Die Spitze steckte genau im Sand oder in einem Gestell an Bord.',2],
        ['Wie hieß der erste Kaiser Roms?','Augustus',['Nero','Hannibal','Trajan'],'Er war der Adoptivsohn Caesars.','Augustus wurde 27 vor Christus der erste Kaiser des Reiches.','Er sagte, er habe Rom aus Ziegeln in Marmor verwandelt.',3],
        ['Welche Erfindung ermöglichte riesige römische Kuppeln?','Beton',['Papier','Glas','Schießpulver'],'Flüssig gegossen, dann steinhart.','Mit Beton aus Vulkanasche bauten sie Kuppeln und Häfen.','Das Pantheon trägt seine Betonkuppel seit zweitausend Jahren.',3],
        ['Welches römische Fest fiel mitten in den Winter?','Saturnalien',['Lupercalien','Olympia','Vestalien'],'Man schenkte sich Kleinigkeiten.','Bei den Saturnalien wurde gefeiert und man beschenkte einander.','Für einen Tag saßen Sklaven am Tisch und die Herren bedienten.',3],
        ['Welche Göttin hütete ein Feuer, das nie ausgehen durfte?','Vesta',['Venus','Juno','Diana'],'Ihr Tempel war rund.','Die Vestalinnen hielten Roms heiliges Feuer Tag und Nacht am Brennen.','Ging es aus, fürchtete man um ganz Rom.',3],
        ['Wie viele Tage hatte die alte römische Woche?','Acht Tage',['Sieben Tage','Fünf Tage','Zehn Tage'],'Der achte Tag war Markttag.','Die römische Woche lief von Markttag zu Markttag, acht Tage lang.','Erst Jahrhunderte später übernahm man die Sieben-Tage-Woche.',3],
        ['In welchem Jahr fiel das Weströmische Reich?','Im Jahr 476',['Im Jahr 1066','Im Jahr 79','Im Jahr 1492'],'Vor gut fünfzehnhundert Jahren.','476 wurde der letzte Kaiser des Westens abgesetzt.','Der östliche Teil bestand noch fast tausend Jahre weiter.',4],
        ['Wie hieß die berühmteste römische Hauptstraße?','Die Via Appia',['Die Via Maris','Die Seidenstraße','Der Limes'],'Sie führt von Rom nach Süden.','Die Via Appia entstand schon 312 vor Christus, von Rom aus südwärts.','Teile davon liegen nach über zweitausend Jahren noch da.',4],
        ['Welcher Feldherr zog mit Elefanten über die Alpen?','Hannibal',['Caesar','Nero','Augustus'],'Er kam aus Karthago.','Hannibal überraschte Rom, indem er Heer und Elefanten über die Berge führte.','Fast keiner seiner Elefanten überlebte den Marsch.',4],
        ['Wie heizten reiche Römer ihr Haus?','Warme Luft unterm Boden',['Mit einem Kohleofen','Mit Tierfellen','Mit warmem Wasser im Bett'],'Im Keller brannte ein Feuer.','Ein Feuer heizte den Raum unter dem Boden, die Wärme stieg auf.','Das hieß Hypokaustum, und der Boden wurde manchmal zu heiß.',4],
        ['Wie viele Menschen lebten um das Jahr 100 in Rom?','Etwa eine Million',['Etwa tausend','Etwa zehntausend','Über hundert Millionen'],'So groß wie eine Großstadt heute.','Rom war damals die größte Stadt der Welt mit rund einer Million Menschen.','Erst um 1800 erreichte eine Stadt in Europa diese Zahl wieder.',4]
      ]
