    wetenschap: {
      lichaam: [
        ['Wie viele Finger hat eine Hand meistens?','Fünf',['Drei','Sieben','Zehn'],'Zähl ruhig nach.','An einer Hand sitzen vier Finger und ein Daumen, zusammen fünf.','Nur der Daumen kann alle anderen Finger berühren.',1],
        ['Womit schmeckst du, ob etwas süß ist?','Mit der Zunge',['Mit den Ohren','Mit den Haaren','Mit dem Ellbogen'],'Sie liegt im Mund.','Auf der Zunge sitzen Tausende winziger Geschmacksknospen.','Ohne Nase schmeckst du viel weniger, darum ist Essen bei Schnupfen fad.',1],
        ['Was braucht dein Körper jede Nacht?','Schlaf',['Sport','Süßigkeiten','Lärm'],'Die Augen fallen von selbst zu.','Im Schlaf repariert sich dein Körper und dein Gehirn räumt den Tag auf.','Kinder wachsen vor allem nachts.',1],
        ['Womit riechst du?','Mit der Nase',['Mit dem Knie','Mit dem Ohr','Mit der Ferse'],'Sie sitzt mitten im Gesicht.','Oben in der Nase sitzen Zellen, die Gerüche ans Gehirn weitergeben.','Ein Mensch erkennt mehr als tausend verschiedene Gerüche.',1],
        ['Wo im Körper sitzt dein Herz?','In der Brust',['Im Fuß','In der Hand','Im Knie'],'Leg die Hand darauf.','Dein Herz liegt zwischen den Lungen, etwas nach links.','Dein Herz ist ungefähr so groß wie deine eigene Faust.',1],
        ['Warum musst du jeden Tag trinken?','Du verlierst ständig Wasser',['Wasser macht größer','Wasser putzt die Zähne','Wasser stärkt die Haare'],'Denk an Schwitzen und Pinkeln.','Du verlierst Wasser durch Schweiß, Pipi und sogar den Atem, also füllst du auf.','Mehr als die Hälfte deines Körpers ist Wasser.',2],
        ['Was macht dein Magen mit dem Essen?','Er knetet es zu Brei',['Er pumpt Blut herum','Er reinigt die Luft','Er steuert die Muskeln'],'Er drückt und mischt.','Muskeln in der Magenwand kneten das Essen, und Säure zersetzt es.','Leer ist der Magen faustgroß, aber er dehnt sich stark.',2],
        ['Was passiert mit deinem Herzschlag beim Rennen?','Er wird schneller',['Er hört auf','Er wird langsamer','Es ändert sich nichts'],'Fühl mal am Hals.','Deine Muskeln brauchen mehr Sauerstoff, also pumpt das Herz schneller.','Nach dem Sport sinkt der Herzschlag Schritt für Schritt wieder.',2],
        ['Warum musst du die Zähne putzen?','Gegen Löcher darin',['Gegen Kopfweh','Gegen Niesen','Gegen Kitzelhusten'],'Bakterien mögen Zucker.','Bakterien machen aus Zuckerresten Säure, und die frisst an den Zähnen.','Zahnschmelz ist das härteste Material deines Körpers.',2],
        ['Was macht dein Körper, wenn dir kalt ist?','Du fängst an zu zittern',['Du fängst an zu schwitzen','Du wirst größer','Du fängst an zu niesen'],'Deine Muskeln zittern schnell.','Zittern ist schnelles Anspannen der Muskeln, und das erzeugt Wärme.','Gänsehaut ist ein Rest aus der Zeit mit dickem Fell.',2],
        ['Wie viel Blut hat ein Erwachsener etwa?','Etwa fünf Liter',['Etwa einen halben Liter','Etwa zwanzig Liter','Etwa fünfzig Liter'],'Fünf Tüten Milch.','In einem erwachsenen Körper stecken rund fünf Liter Blut.','Dieses Blut dreht jeden Tag eine lange Runde durch den ganzen Körper.',3],
        ['Welcher Knochen ist der kleinste im Körper?','Der Steigbügel',['Das Nasenbein','Ein Fingerglied','Die kleinste Rippe'],'Er sitzt im Ohr.','Der Steigbügel im Mittelohr ist nur wenige Millimeter groß.','Mit Hammer und Amboss gibt er den Schall nach innen weiter.',3],
        ['Warum brauchst du zwei Augen?','Um Tiefe zu sehen',['Um weiter zu sehen','Um schneller zu lesen','Um blinzeln zu können'],'Schließ eins und greif nach etwas.','Jedes Auge sieht etwas anderes, und dein Gehirn macht daraus Tiefe.','Darum ist Fangen mit einem Auge viel schwerer.',3],
        ['Was tun rote Blutkörperchen?','Sie bringen Sauerstoff',['Sie bauen Knochen','Sie verdauen das Essen','Sie senden Signale'],'Sie holen ihn in der Lunge.','Rote Blutkörperchen laden Sauerstoff in der Lunge und liefern ihn im Körper aus.','In einem Blutstropfen stecken Millionen davon.',3],
        ['Wie schnell kann ein Nervensignal reisen?','Über 400 Kilometer je Stunde',['So schnell wie eine Schnecke','So schnell wie ein Fahrrad','So schnell wie das Licht'],'Schneller als ein Rennwagen.','Die schnellsten Nerven geben einen Reiz mit über hundert Metern je Sekunde weiter.','Darum ziehst du die Hand weg, bevor du den Schmerz spürst.',3],
        ['Wie oft atmest du ungefähr am Tag?','Etwa 20.000 Mal',['Etwa 200 Mal','Etwa 2.000 Mal','Etwa 2 Millionen Mal'],'Rund fünfzehn Mal pro Minute.','Ein Kind atmet etwa zwanzigtausend Mal am Tag, ohne daran zu denken.','Du musst nie daran denken, das regelt dein Hirnstamm.',4],
        ['Welches Organ macht Galle, um Fett zu verdauen?','Die Leber',['Die Lunge','Die Milz','Die Nieren'],'Sie liegt rechts unter den Rippen.','Die Leber macht Galle, die Fett in winzige Tröpfchen zerlegt.','Die Leber ist das einzige Organ, das nachwachsen kann.',4],
        ['Wo entstehen neue Blutkörperchen?','Im Knochenmark',['Im Magen','In der Haut','Im Herzen'],'Tief in den Knochen.','Im weichen Mark der Knochen entstehen jede Sekunde Millionen Blutkörperchen.','Ein rotes Blutkörperchen lebt etwa vier Monate.',4],
        ['Wie heißt der schwarze Kreis, der Licht ins Auge lässt?','Die Pupille',['Das Augenlid','Die Augenbraue','Der Tränenkanal'],'Im Dunkeln wird er größer.','Die Pupille ist die Öffnung für das Licht; die Iris stellt die Weite ein.','Im Dunkeln öffnet sie sich bis zu dreimal so weit.',4],
        ['Warum kannst du nicht schlucken und atmen zugleich?','Ein Deckel schließt zu',['Die Zunge ist zu groß','Die Lunge steht still','Der Magen drückt zurück'],'Ein Klappdeckel geht zu.','Beim Schlucken klappt der Kehldeckel über die Luftröhre, damit Essen richtig läuft.','Geht das schief, verschluckst du dich und musst husten.',4]
      ],
      natuur_energie: [
        ['Was wandeln Solarzellen in Strom um?','Sonnenlicht',['Regen','Wind','Schnee'],'Es kommt von sehr weit her.','In einer Solarzelle schlagen Lichtteilchen Strom aus einer Siliziumschicht heraus.','Auch an einem kalten Tag arbeiten Module gut, wenn nur Licht da ist.',1],
        ['Was kannst du zu Hause tun, um Energie zu sparen?','Das Licht ausmachen',['Alle Lampen anmachen','Die Tür offen lassen','Den Hahn laufen lassen'],'Denk an ein leeres Zimmer.','Was ausgeschaltet ist, verbraucht überhaupt keinen Strom.','Geräte im Stand-by verbrauchen zusammen ganz schön viel.',1],
        ['Welcher Kraftstoff kommt in ein normales Auto?','Benzin',['Milch','Wasser','Sand'],'Man tankt es an der Säule.','Benzin und Diesel stammen aus Erdöl und verbrennen im Motor.','Von einer vollen Tankfüllung wird nur etwa ein Drittel wirklich Bewegung.',1],
        ['Was kommt aus einer Steckdose?','Strom',['Luft','Wasser','Sand'],'Man sieht ihn nicht, aber er wirkt.','Aus der Steckdose kommt elektrischer Strom, der über Kabel geliefert wird.','Steck dort nie etwas anderes hinein als einen Stecker.',1],
        ['Welches Auto fährt ohne Abgase?','Ein Elektroauto',['Ein Dieselauto','Ein Moped','Ein Düsenjet'],'Es wird aufgeladen.','Ein Elektroauto hat keinen Auspuff; der Strom kommt aus einem Akku.','Wie sauber es wirklich ist, hängt davon ab, wie der Strom gemacht wurde.',1],
        ['Warum stellt man Windräder aufs Meer?','Dort weht es kräftiger',['Dort ist es wärmer','Dort regnet es weniger','Dort ist es leiser'],'Keine Häuser oder Bäume im Weg.','Auf dem Meer weht fast immer Wind, und nichts bremst ihn ab.','Ein großes Windrad auf See versorgt Tausende Haushalte.',2],
        ['Was passiert mit einer brennenden Glühlampe?','Sie wird heiß',['Sie wird kalt','Sie wird schwer','Sie wird nass'],'Fass sie lieber nicht an.','Der größte Teil der Energie wird Wärme statt Licht.','Darum ist eine LED viel sparsamer: Sie bleibt fast kühl.',2],
        ['Was bewirkt Doppelglas im Fenster?','Es hält Wärme drinnen',['Es macht Licht heller','Es färbt das Licht','Es macht das Glas dünner'],'Zwischen zwei Scheiben ist Luft.','Die Luft- oder Gasschicht zwischen den Scheiben lässt Wärme viel schlechter durch.','Im Winter bleibt die innere Scheibe dadurch warm genug und beschlägt nicht.',2],
        ['Woher kommt Erdgas?','Tief aus dem Boden',['Aus den Wolken','Aus Meerwasser','Aus Bäumen'],'Man bohrt danach.','Erdgas steckt in winzigen Poren im Gestein, Kilometer unter der Oberfläche.','Es entstand aus Resten von Pflanzen und Tierchen vor Millionen Jahren.',2],
        ['Was macht ein Dynamo am Fahrrad?','Er erzeugt Strom',['Er bremst das Rad','Er pumpt den Reifen auf','Er misst die Geschwindigkeit'],'Du musst dafür treten.','Das drehende Rad dreht einen Magneten, und das erzeugt Strom.','Darum tritt sich ein Rad mit Dynamo etwas schwerer.',2],
        ['Warum stehen Windräder manchmal still?','Zu wenig oder zu viel Wind',['Sie laden gerade auf','Sie ruhen nachts','Sie sind dann voll'],'Auch Sturm ist ein Problem.','Bei zu wenig Wind kommen sie nicht in Gang, bei Sturm dreht man sie aus dem Wind.','So schützen sie ihre eigenen Flügel vor Schäden.',3],
        ['Was misst eine Kilowattstunde?','Wie viel Strom du brauchst',['Wie warm es draußen ist','Wie stark der Wind weht','Wie viel Wasser du brauchst'],'Sie steht auf der Stromrechnung.','Eine Kilowattstunde heißt: eine Stunde lang tausend Watt verbrauchen.','Eine LED-Lampe brennt damit gut hundert Stunden.',3],
        ['Warum heißt Holz ein erneuerbarer Brennstoff?','Es wachsen neue Bäume',['Es brennt nicht','Es ist sehr alt','Es kommt aus dem Bergwerk'],'Man kann es neu wachsen lassen.','Neue Bäume nehmen wieder Kohlendioxid auf, der Brennstoff wächst also nach.','Das stimmt nur, wenn so viel nachgepflanzt wie gefällt wird.',3],
        ['Was geschieht in einem Kernkraftwerk?','Atome werden gespalten',['Kohle wird verbrannt','Wasser wird gespalten','Wind wird gespeichert'],'Dabei wird sehr viel Wärme frei.','Beim Spalten von Uran wird Wärme frei, die Wasser zu Dampf macht.','Dieser Dampf treibt eine Turbine an, wie in jedem Kraftwerk.',3],
        ['Warum zeigen Solarmodule oft nach Süden?','Dort steht die Sonne lang',['Dort ist die Luft sauberer','Dort weht es weniger','Dort ist das Dach stärker'],'Folge der Bahn der Sonne.','Nördlich des Äquators steht die Sonne den größten Teil des Tages im Süden.','Module nach Ost und West liefern am Tag weniger, aber gleichmäßiger.',3],
        ['Wie viel Energie einer Glühlampe wird Licht?','Etwa fünf Prozent',['Etwa die Hälfte','Fast alles','Etwa achtzig Prozent'],'Den Rest spürst du als Wärme.','Von einer Glühlampe wird nur ein kleiner Teil Licht, der Rest ist Wärme.','Eine LED holt aus demselben Strom etwa zehnmal so viel Licht.',4],
        ['Was macht eine Wärmepumpe?','Sie holt Wärme aus der Luft',['Sie macht Wärme aus Kohle','Sie pumpt heißes Wasser','Sie verbrennt Gas sparsam'],'Wie ein umgekehrter Kühlschrank.','Eine Wärmepumpe bringt Wärme von draußen nach drinnen, statt sie zu erzeugen.','Selbst bei Frost steckt in der Außenluft noch genug Wärme.',4],
        ['Warum arbeitet ein Solarmodul auch bei Wolken?','Es kommt noch Licht durch',['Es läuft mit Regen','Es speichert Wolken','Es dreht dann schneller'],'Draußen ist es immer noch hell.','Wolken halten viel Licht zurück, aber nicht alles, also liefert das Modul weniger.','An einem grauen Tag schafft ein Modul oft noch ein Viertel seiner Leistung.',4],
        ['Warum fließt Strom mit hoher Spannung übers Land?','So geht weniger verloren',['So fließt er schneller','So ist er billiger','So bleibt das Kabel dünn'],'Sonst wird das Kabel heiß.','Bei hoher Spannung fließt weniger Strom im Kabel, also geht weniger als Wärme verloren.','In der Nähe deines Hauses wird die Spannung wieder gesenkt.',4],
        ['Was passiert, wenn alle gleichzeitig viel Strom brauchen?','Das Netz wird überlastet',['Der Strom wird wärmer','Die Sonne scheint stärker','Die Kabel werden länger'],'Denk an eine zu volle Straße.','Das Netz trägt nur eine bestimmte Menge, danach muss mehr zugeschaltet werden.','Darum hilft es, die Waschmaschine zu einer ruhigen Zeit laufen zu lassen.',4]
      ],
      slimme_proefjes: [
        ['Was passiert, wenn du einen aufgeblasenen Luftballon loslässt?','Er fliegt davon',['Er wird schwerer','Er schmilzt','Er bleibt hängen'],'Die Luft muss irgendwohin.','Die Luft schießt an einer Seite heraus und drückt den Ballon in die andere Richtung.','Eine Rakete funktioniert genau so.',1],
        ['Was schwimmt auf Wasser?','Ein Stück Holz',['Ein Stein','Ein Nagel','Eine Münze'],'Es kommt von einem Baum.','Holz ist leichter als die gleiche Menge Wasser, darum bleibt es oben.','Manche tropischen Hölzer sind so schwer, dass sie untergehen.',1],
        ['Was passiert mit Wasser im Gefrierfach?','Es wird zu Eis',['Es verschwindet','Es wird salzig','Es wird warm'],'Unter null Grad.','Bei null Grad kommen die Wasserteilchen fast zum Stillstand und bilden ein festes Gitter.','Dieses Gitter macht Eis auch größer als das Wasser vorher.',1],
        ['Womit hebst du Nägel auf, ohne sie anzufassen?','Mit einem Magneten',['Mit einem Schwamm','Mit Papier','Mit einem Strohhalm'],'Eisen springt daran.','Ein Magnet zieht Eisen und Stahl an, sogar durch Papier hindurch.','Auf Kupfer, Gold oder Aluminium wirkt ein Magnet nicht.',1],
        ['Welche Farbe wird in der Sonne am schnellsten warm?','Schwarz',['Weiß','Silber','Durchsichtig'],'Denk an eine dunkle Jacke im Sommer.','Schwarz schluckt fast alles Licht und macht daraus Wärme.','Weiß wirft das Licht zurück und bleibt darum kühler.',1],
        ['Warum sinkt ein Nagel, aber ein großes Schiff schwimmt?','Das Schiff ist voller Luft',['Das Schiff ist sehr leicht','Eisen schwimmt immer','Der Motor hält es oben'],'Schau auf die Form, nicht das Gewicht.','Ein Schiff verdrängt viel Wasser, weil Luft darin ist, und das hält es oben.','Kommt Wasser hinein, ist die Luft weg und das Schiff sinkt doch.',2],
        ['Was passiert, wenn du Seife zu Pfeffer auf Wasser gibst?','Der Pfeffer schießt weg',['Der Pfeffer sinkt sofort','Das Wasser wird grün','Der Pfeffer löst sich auf'],'Es geht blitzschnell.','Seife schwächt das Häutchen auf dem Wasser, und das zieht den Pfeffer zum Rand.','Dasselbe Häutchen lässt eine Büroklammer schwimmen.',2],
        ['Was macht Rotkohlsaft, wenn du Essig dazugibst?','Die Farbe ändert sich',['Das Wasser gefriert','Der Saft verschwindet','Es raucht'],'Violett wird rosa.','Rotkohlsaft ist ein Indikator: in Säure rosa, in Seifenwasser grün.','So hast du einen pH-Test aus der Küche.',2],
        ['Was passiert mit einem Ei, das einen Tag in Essig liegt?','Die Schale verschwindet',['Das Ei wird grün','Das Ei kocht','Das Ei schrumpft'],'Sofort steigen Bläschen auf.','Die Säure löst die Kalkschale, übrig bleibt ein hüpfendes Ei in einem Häutchen.','Dieselbe Säure greift auch Zahnschmelz an.',2],
        ['Wie sieht ein Strohhalm schräg im Wasserglas aus?','Er sieht geknickt aus',['Er wird wirklich krumm','Er löst sich auf','Er wird dicker'],'Schau von der Seite.','Licht ändert die Richtung beim Übergang von Wasser zu Luft, darum wirkt er gebrochen.','Dasselbe Brechen von Licht macht einen Regenbogen.',2],
        ['Warum änderst du bei einem Versuch nur eine Sache?','So weißt du, was es war',['So geht es schneller','So ist es ordentlicher','So musst du nicht messen'],'Sonst hast du zwei Verdächtige.','Änderst du zwei Dinge, weißt du nicht, welches den Unterschied gemacht hat.','Darum halten Forscher alles gleich außer dieser einen Größe.',3],
        ['Warum schwimmt eine Büroklammer, wenn du sie sacht hinlegst?','Durch Oberflächenspannung',['Weil Stahl leicht ist','Wegen des Windes','Wegen Magnetismus'],'Das Wasser hat ein Häutchen.','Wasserteilchen ziehen aneinander und bilden oben ein Häutchen, das die Klammer trägt.','Wasserläufer laufen auf genau diesem Häutchen.',3],
        ['Warum wird ein aufgeschnittener Apfel braun?','Durch Sauerstoff der Luft',['Durch das Licht','Durch das Messer','Durch Wasser'],'Zitronensaft hilft dagegen.','Stoffe im Apfel reagieren mit Sauerstoff und bilden eine braune Schicht.','Zitronensaft bremst diese Reaktion, weil er sauer ist.',3],
        ['Wie erkennst du, ob ein Ei noch frisch ist?','Ein frisches Ei sinkt',['Ein frisches Ei schwimmt','Ein frisches Ei ist warm','Ein frisches Ei klappert'],'Leg es in ein Glas Wasser.','In einem alten Ei ist mehr Luft, es steigt auf; ein frisches bleibt liegen.','Durch die Schale entweicht langsam Feuchtigkeit, die Luftblase wächst.',3],
        ['Was macht Zucker in heißem Wasser im Vergleich zu kaltem?','Er löst sich schneller',['Er löst sich langsamer','Er löst sich gar nicht','Er wird salzig'],'Rühr mal im Tee.','In heißem Wasser bewegen sich die Teilchen schneller und reißen die Körner rascher auseinander.','In heißem Wasser passt außerdem viel mehr Zucker hinein.',3],
        ['Was ist eine Kontrollgruppe im Versuch?','Die Gruppe ohne Änderung',['Die Gruppe, die misst','Die Gruppe, die gewinnt','Die Gruppe, die aufräumt'],'Mit ihr vergleichst du.','Die Kontrollgruppe bekommt die Änderung nicht, so siehst du, was ohne sie passiert.','Ohne sie weißt du nie, ob dein Eingriff den Unterschied machte.',4],
        ['Warum steigt Limo hoch, wenn du am Strohhalm saugst?','Der Luftdruck drückt mit',['Du ziehst das Wasser hoch','Die Limo ist sehr leicht','Der Halm saugt selbst'],'Die Luft draußen drückt mit.','Du holst Luft aus dem Halm, und der Luftdruck auf das Glas drückt die Limo nach oben.','Über etwa zehn Meter klappt Saugen nicht mehr, egal wie stark.',4],
        ['Was ist der weiße Dampf über einer Tasse Tee?','Dampf wird zu Tröpfchen',['Es ist Rauch','Es ist warme Luft','Es ist Staub'],'Du siehst ihn erst in kühler Luft.','Unsichtbarer Wasserdampf kühlt ab und bildet winzige Tröpfchen, und die siehst du.','Eine Wolke am Himmel besteht aus genau solchen Tröpfchen.',4],
        ['Was macht ein Lackmuspapier?','Es prüft, ob etwas sauer ist',['Es misst die Temperatur','Es misst das Gewicht','Es misst die Geschwindigkeit'],'Es färbt sich sofort.','Lackmus wird in Säure rot und in Lauge blau, so siehst du den Unterschied.','Rotkohlsaft macht dasselbe, nur in Violett, Rosa und Grün.',4],
        ['Warum garen Kartoffeln im Schnellkochtopf schneller?','Druck macht Wasser heißer',['Die Flamme ist heißer','Es ist mehr Salz drin','Der Topf ist aus Kupfer'],'Der Dampf kann nicht raus.','Unter hohem Druck kocht Wasser erst über hundert Grad, und heißeres Wasser gart schneller.','Hoch in den Bergen ist es umgekehrt: Dort kocht Wasser schon bei neunzig Grad.',4]
      ]
    }
